import { isNonEmptyString } from './guards';

const mystery: unknown = 'hello';
if (isNonEmptyString(mystery)) {
  // narrowing must make this compile without casts
  mystery.toUpperCase();
}

// @ts-expect-error - without the guard, unknown has no string methods
mystery.toUpperCase();

test_setup_files.behavior_test.js:
const assert = require('assert');
const { isNonEmptyString } = require('./build/guards.js');
assert.strictEqual(isNonEmptyString('hi'), true);
assert.strictEqual(isNonEmptyString('  x  '), true);
assert.strictEqual(isNonEmptyString(''), false);
assert.strictEqual(isNonEmptyString('   '), false, 'whitespace-only is not non-empty');
assert.strictEqual(isNonEmptyString(42), false);
assert.strictEqual(isNonEmptyString(null), false);
assert.strictEqual(isNonEmptyString(['a']), false);
console.log('PASS');

reference_solution.guards.ts:
export function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

